export const createScene = function (engine, canvas, BABYLON) {
  var scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.15, 0.15, 0.15);

  var hkPlugin = BABYLON.PHYSICS_HAVOK;
  if (!hkPlugin) {
    console.error("Havok Plugin is not available in injected modules!");
    return scene;
  }
  console.log("Using successfully loaded Havok Instance:", hkPlugin);

  var camera = new BABYLON.FreeCamera("camera1", new BABYLON.Vector3(0, 15, -35), scene);
  camera.setTarget(BABYLON.Vector3.Zero());
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.7;

  var glowLayer = new BABYLON.GlowLayer("glow", scene);
  glowLayer.intensity = 1.5;

  var groundMaterial = new BABYLON.GridMaterial("groundMaterial", scene);
  groundMaterial.majorUnitFrequency = 5;
  groundMaterial.minorUnitVisibility = 0.5;
  groundMaterial.gridRatio = 2;
  groundMaterial.opacity = 0.99;
  groundMaterial.useMaxLine = true;

  var ground = BABYLON.MeshBuilder.CreateGround("ground", { width: 500, height: 500 }, scene);
  ground.material = groundMaterial;

  if (BABYLON.GUI) {
    var advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");
    var instructions = new BABYLON.GUI.TextBlock();
    instructions.text = "좌클릭 : 번개 타격 및 파괴\n우클릭 유지 : 시간 역행";
    instructions.color = "white";
    instructions.fontSize = 22;
    instructions.fontWeight = "bold";
    instructions.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_RIGHT;
    instructions.textVerticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_CENTER;
    instructions.paddingRight = "40px";
    instructions.textWrapping = true;
    advancedTexture.addControl(instructions);
  }

  var breakableObjects = [];
  var allFragments = [];
  var isRewinding = false;
  var maxHistoryFrames = 300;

  var numObjects = Math.floor(Math.random() * 3) + 3;

  for (var i = 0; i < numObjects; i++) {
    var shapeType = Math.floor(Math.random() * 3);
    var breakableObj;

    if (shapeType === 0) breakableObj = BABYLON.MeshBuilder.CreateBox("breakable", { size: 3 }, scene);
    else if (shapeType === 1) breakableObj = BABYLON.MeshBuilder.CreateSphere("breakable", { diameter: 3.5, segments: 12 }, scene);
    else breakableObj = BABYLON.MeshBuilder.CreateCylinder("breakable", { height: 4, diameter: 2.5, tessellation: 12 }, scene);

    breakableObj.position = new BABYLON.Vector3((Math.random() - 0.5) * 25, 3, (Math.random() - 0.5) * 30);

    var mat = new BABYLON.StandardMaterial("boxMat", scene);
    mat.diffuseColor = BABYLON.Color3.Random();
    breakableObj.material = mat;

    breakableObj.originalTransform = {
      p: breakableObj.position.clone(),
      q: breakableObj.rotationQuaternion ? breakableObj.rotationQuaternion.clone() : breakableObj.rotation.toQuaternion(),
    };

    breakableObjects.push(breakableObj);
  }

  var baseCutBox = BABYLON.MeshBuilder.CreateBox("baseCut", { size: 30 }, scene);
  baseCutBox.position.x = 15;
  baseCutBox.bakeCurrentTransformIntoVertices();
  baseCutBox.isVisible = false;

  // =========================================================
  // 물리 엔진 즉시 활성화 및 Aggregate 연결 (스코프 통합)
  // =========================================================
  scene.enablePhysics(new BABYLON.Vector3(0, -9.81, 0), hkPlugin);

  new BABYLON.PhysicsAggregate(ground, BABYLON.PhysicsShapeType.BOX, { mass: 0, friction: 0.9, restitution: 0.01 }, scene);

  for (var i = 0; i < breakableObjects.length; i++) {
    breakableObjects[i].aggregate = new BABYLON.PhysicsAggregate(breakableObjects[i], BABYLON.PhysicsShapeType.CONVEX_HULL, { mass: 1 }, scene);
  }

  // =========================================================
  // 함수 및 이벤트 리스너 선언
  // =========================================================
  function createLightning(hitPoint) {
    var points = [];
    var startPoint = new BABYLON.Vector3(hitPoint.x + (Math.random() - 0.5) * 5, hitPoint.y + 20, hitPoint.z + (Math.random() - 0.5) * 5);
    var currentPoint = startPoint;
    points.push(currentPoint);

    var segments = 10;
    for (var i = 0; i < segments; i++) {
      var isLast = i === segments - 1;
      currentPoint = isLast
        ? hitPoint
        : new BABYLON.Vector3(
            currentPoint.x + (Math.random() - 0.5) * 3,
            currentPoint.y - (startPoint.y - hitPoint.y) / segments,
            currentPoint.z + (Math.random() - 0.5) * 3,
          );
      points.push(currentPoint);
    }

    var lightning = BABYLON.MeshBuilder.CreateTube("lightning", { path: points, radius: 0.15, updatable: false }, scene);
    var lightMat = new BABYLON.StandardMaterial("lightMat", scene);
    lightMat.emissiveColor = new BABYLON.Color3(0.4, 0.8, 1.0);
    lightMat.disableLighting = true;
    lightning.material = lightMat;

    var alpha = 1.0;
    var fadeObserver = scene.onBeforeRenderObservable.add(function () {
      alpha -= 0.1;
      lightning.visibility = alpha;
      if (alpha <= 0) {
        scene.onBeforeRenderObservable.remove(fadeObserver);
        lightning.dispose();
        lightMat.dispose();
      }
    });
  }

  canvas.oncontextmenu = function (e) {
    e.preventDefault();
  };

  scene.onPointerObservable.add((pointerInfo) => {
    if (pointerInfo.type === BABYLON.PointerEventTypes.POINTERDOWN && pointerInfo.event.button === 2) {
      isRewinding = true;
      allFragments.forEach((f) => {
        if (!f.isDisposed() && f.aggregate) {
          f.aggregate.dispose();
          f.aggregate = null;
        }
      });
    } else if (pointerInfo.type === BABYLON.PointerEventTypes.POINTERUP && pointerInfo.event.button === 2) {
      isRewinding = false;

      allFragments.forEach((f) => {
        if (f.isDisposed()) return;
        var isFullyRewound = f.history.length === 0;
        var originMesh = f.parentMesh;

        if (isFullyRewound) {
          if (originMesh && !originMesh.isRecovered) {
            originMesh.position.copyFrom(originMesh.originalTransform.p);
            if (originMesh.rotationQuaternion) originMesh.rotationQuaternion.copyFrom(originMesh.originalTransform.q);

            originMesh.isVisible = true;
            originMesh.aggregate = new BABYLON.PhysicsAggregate(originMesh, BABYLON.PhysicsShapeType.CONVEX_HULL, { mass: 1 }, scene);
            originMesh.name = "breakable";
            originMesh.isRecovered = true;
          }
          f.dispose();
        } else {
          f.aggregate = new BABYLON.PhysicsAggregate(f, BABYLON.PhysicsShapeType.CONVEX_HULL, { mass: 0.2, restitution: 0.05, friction: 0.9 }, scene);
          if (f.aggregate.body.setLinearDamping) {
            f.aggregate.body.setLinearDamping(0.4);
            f.aggregate.body.setAngularDamping(0.4);
          }
        }
      });
      allFragments = allFragments.filter((f) => !f.isDisposed());
    }
  });

  scene.onPointerDown = function (evt, pickResult) {
    if (evt.button === 0 && pickResult.hit && pickResult.pickedMesh && pickResult.pickedMesh.name === "breakable") {
      var originalMesh = pickResult.pickedMesh;
      var hitPoint = pickResult.pickedPoint;

      createLightning(hitPoint);

      if (originalMesh.aggregate) {
        originalMesh.aggregate.dispose();
        originalMesh.aggregate = null;
      }

      originalMesh.isVisible = false;
      originalMesh.isRecovered = false;

      var cloneForCut = originalMesh.clone(originalMesh.name + "_clone");
      cloneForCut.isVisible = true;

      var parts = [cloneForCut];
      var minFragments = 12;
      var attempts = 0;

      while (parts.length < minFragments && attempts < 40) {
        attempts++;
        var idx = Math.floor(Math.random() * parts.length);
        var target = parts[idx];

        target.computeWorldMatrix(true);
        target.refreshBoundingInfo();

        var cutBox = baseCutBox.clone("cut");
        cutBox.isVisible = true;

        if (attempts === 1) cutBox.position = BABYLON.Vector3.TransformCoordinates(hitPoint, target.getWorldMatrix().clone().invert()).clone();
        else {
          cutBox.position = target.getBoundingInfo().boundingBox.center.clone();
          cutBox.position.addInPlace(new BABYLON.Vector3((Math.random() - 0.5) * 0.8, (Math.random() - 0.5) * 0.8, (Math.random() - 0.5) * 0.8));
        }

        cutBox.rotation = new BABYLON.Vector3(Math.random() * Math.PI, Math.random() * Math.PI, Math.random() * Math.PI);
        cutBox.bakeCurrentTransformIntoVertices();

        var csgMesh = BABYLON.CSG.FromMesh(target);
        var csgCut = BABYLON.CSG.FromMesh(cutBox);

        var m1 = csgMesh.intersect(csgCut).toMesh(target.name + "_p1", target.material, scene, false);
        var m2 = csgMesh.subtract(csgCut).toMesh(target.name + "_p2", target.material, scene, false);

        m1.position.copyFrom(target.position);
        if (target.rotationQuaternion) m1.rotationQuaternion = target.rotationQuaternion.clone();
        else m1.rotation.copyFrom(target.rotation);

        m2.position.copyFrom(target.position);
        if (target.rotationQuaternion) m2.rotationQuaternion = target.rotationQuaternion.clone();
        else m2.rotation.copyFrom(target.rotation);

        if (m1.getTotalVertices() > 0 && m2.getTotalVertices() > 0) {
          parts.splice(idx, 1, m1, m2);
          target.dispose();
        } else {
          m1.dispose();
          m2.dispose();
        }
        cutBox.dispose();
      }

      if (parts.length === 1) {
        parts[0].dispose();
        originalMesh.isVisible = true;
        originalMesh.aggregate = new BABYLON.PhysicsAggregate(originalMesh, BABYLON.PhysicsShapeType.CONVEX_HULL, { mass: 1 }, scene);
        return;
      }

      for (var k = 0; k < parts.length; k++) {
        var p = parts[k];
        p.name = "fragment";
        p.refreshBoundingInfo();

        var centerWorld = p.getBoundingInfo().boundingBox.centerWorld.clone();
        p.position.subtractInPlace(centerWorld);
        p.bakeCurrentTransformIntoVertices();
        p.position.copyFrom(centerWorld);

        p.parentMesh = originalMesh;
        p.history = [];

        p.history.push({
          p: p.position.clone(),
          q: p.rotationQuaternion ? p.rotationQuaternion.clone() : p.rotation.toQuaternion(),
        });

        p.aggregate = new BABYLON.PhysicsAggregate(p, BABYLON.PhysicsShapeType.CONVEX_HULL, { mass: 0.2, restitution: 0.05, friction: 0.9 }, scene);

        if (p.aggregate.body.setLinearDamping) {
          p.aggregate.body.setLinearDamping(0.4);
          p.aggregate.body.setAngularDamping(0.4);
        }

        var impulseDir = p.position.subtract(hitPoint).normalize();
        impulseDir.y += 0.3;
        impulseDir.normalize();
        p.aggregate.body.applyImpulse(impulseDir.scale(Math.random() * 1.5 + 0.5), hitPoint);

        allFragments.push(p);
      }
    }
  };

  scene.onBeforeRenderObservable.add(function () {
    for (var i = 0; i < allFragments.length; i++) {
      var f = allFragments[i];
      if (f.isDisposed()) continue;

      if (!isRewinding) {
        if (f.history.length > maxHistoryFrames) f.history.shift();
        f.history.push({
          p: f.position.clone(),
          q: f.rotationQuaternion ? f.rotationQuaternion.clone() : f.rotation.toQuaternion(),
        });
      } else {
        for (var step = 0; step < 2; step++) {
          if (f.history.length > 0) {
            var pastState = f.history.pop();
            f.position.copyFrom(pastState.p);
            if (f.rotationQuaternion) f.rotationQuaternion.copyFrom(pastState.q);
          }
        }
      }
    }
  });

  return scene;
};
